<ref name="kim">{{Cytuj pismo | autor = Kim, Nam C.; Van Toi, Lai; Hiep, Trinh Hoang | tytuł = Co Loa: An Investigation of Vietnam's Ancient Capital  | czasopismo = Antiquity | wydawca =  Antiquity Publications Ltd. | wydanie = 326  | wolumin =  84 | strony = 1011 | język = en | data = 2010-12 | url = https://www.questia.com/article/1G1-250133904/co-loa-an-investigation-of-vietnam-s-ancient-capital}}</ref>
